<?php
/**
 * Plugin Name: NESPORTS3 Updater V57 (Story & Helpers Hotfix)
 * Description: Ensures helpers.php and widget-story.php are fully in sync with nesports_setting() on live server.
 * Version: 57.0
 * Author: NESports
 */

if (!defined('ABSPATH')) exit;

function run_nesports_v57_sync() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store',
        WP_PLUGIN_DIR . '/nesports-custom'
    );
    if (is_dir(WP_PLUGIN_DIR)) {
        $files = scandir(WP_PLUGIN_DIR);
        foreach ($files as $f) {
            if ($f === '.' || $f === '..') continue;
            if (stripos($f, 'nesport') !== false) {
                $full = WP_PLUGIN_DIR . '/' . $f;
                if (is_dir($full) && !in_array($full, $target_dirs)) {
                    $target_dirs[] = $full;
                }
            }
        }
    }

    $payloads = array(
        'includes/helpers.php' => base64_decode(''),
        'includes/class-nesports-admin.php' => base64_decode(''),
        'includes/elementor-widgets/widget-story.php' => base64_decode(''),
        'templates/page-story.php' => base64_decode(''),
        'templates/page-contact.php' => base64_decode(''),
        'templates/header-nesports.php' => base64_decode(''),
        'templates/footer-nesports.php' => base64_decode(''),
        'assets/css/nesports-admin.css' => base64_decode(''),

    );

    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                if (function_exists('wp_mkdir_p')) {
                    wp_mkdir_p($d);
                } else {
                    @mkdir($d, 0755, true);
                }
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }

    // Deactivate old updaters
    if (function_exists('deactivate_plugins')) {
        $old_plugins = array(
            'nesports-updater-v54/nesports-updater-v54.php',
            'nesports-updater-v55/nesports-updater-v55.php',
            'nesports-updater-v56/nesports-updater-v56.php'
        );
        deactivate_plugins($old_plugins, true);
    }

    // Clear Elementor Cache
    if (class_exists('\Elementor\Plugin')) {
        \Elementor\Plugin::$instance->files_manager->clear_cache();
    }

    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_v57']) && $_GET['nesports_apply_v57'] === '1') {
        $res = run_nesports_v57_sync();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
    run_nesports_v57_sync();
}, 1);

register_activation_hook(__FILE__, 'run_nesports_v57_sync');
